package com.safaan.worldforge;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import com.safaan.worldforge.engine.world.World;import com.safaan.worldforge.engine.rendering.WorldRenderer;
public final class MainActivity extends Activity{
 WorldRenderer r; public void onCreate(Bundle b){super.onCreate(b);getWindow().setFlags(1024,1024);World w=new World(getPreferences(0).getLong("seed",1234567L));r=new WorldRenderer(w);FrameLayout root=new FrameLayout(this);GLView gl=new GLView();root.addView(gl);TextView cross=t("+");FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(70,70,Gravity.CENTER);root.addView(cross,cp);LinearLayout bar=new LinearLayout(this);bar.setOrientation(LinearLayout.HORIZONTAL);for(int i=0;i<8;i++){Button q=new Button(this);q.setText(String.valueOf(i+1));q.setTextSize(14);bar.addView(q,new LinearLayout.LayoutParams(0,64,1));}FrameLayout.LayoutParams bp=new FrameLayout.LayoutParams(-1,70,Gravity.BOTTOM);bp.setMargins(180,0,180,24);root.addView(bar,bp);Button jump=new Button(this);jump.setText("JUMP");FrameLayout.LayoutParams jp=new FrameLayout.LayoutParams(150,100,Gravity.RIGHT|Gravity.BOTTOM);jp.setMargins(0,0,28,110);root.addView(jump,jp);jump.setOnClickListener(v->r.y+=1.5f);setContentView(root);}
 TextView t(String s){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(32);v.setGravity(17);return v;}
 final class GLView extends android.opengl.GLSurfaceView{long last;float lx,ly;GLView(){super(MainActivity.this);setEGLContextClientVersion(2);setRenderer(r);setRenderMode(RENDERMODE_CONTINUOUSLY);last=System.nanoTime();}public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()==2){float dx=e.getX()-lx,dy=e.getY()-ly;if(e.getX()>getWidth()/2)r.turn(dx,dy);else r.move(-dy/80f,dx/80f,.016f);}lx=e.getX();ly=e.getY();return true;}}
}
